      hu: ["Hivatalos neve Krung Thep Mahanakhon.", "Több mint 8 millió lakosa van.", "A Nagy Palota egy fő látványosság."],
      ro: ["Numele oficial este Krung Thep Mahanakhon.", "Are peste 8 milioane de locuitori.", "Marele Palat este o atracție majoră."],
      en: ["Full ceremonial name is Krung Thep Mahanakhon.", "Has a population of over 8 million.", "The Grand Palace is a major attraction."],
