      pt: ["Trang é uma cidade no sul da Tailândia, perto da costa do mar de Andamão, conhecida pela sua cena culinária.", "Situada no território do Reino da Tailândia.", "Marcada pelo clima de monção do sudeste asiático.", "Vinculada ao legado de Sukhothai e Ayutthaya."],
      fr: ["Trang est une ville du sud de la Thaïlande près de la côte de la mer d'Andaman, connue pour sa scène culinaire.", "Située sur le territoire du Royaume de Thaïlande.", "Marquée par le climat de mousson de l'Asie du Sud-Est.", "Liée à l'héritage de Sukhothai et Ayutthaya."],
