    name: {
      de: "Samut Prakan",
      hu: "Szamutprakan",
      ro: "Samut Prakan",
      en: "Samut Prakan"},
    image: "/poi-images/samut-prakan-cities-v2.webp",
    descriptionAdvanced: {
      de: "Samut Prakan, oft auch als \"Pak Nam\" (Mündung des Flusses) bezeichnet, liegt am Zusammenfluss des Chao Phraya mit dem Golf von Thailand. Die Stadt wurde während der Ayutthaya-Periode gegründet und diente aufgrund ihrer Lage am Meer jahrhundertelang als strategischer Verteidigungsposten für die Hauptstadt. Historische Festungen wie Phra Chulachomklao zeugen von der militärischen Bedeutung der Region im 19. Jahrhundert. Geografisch ist die Stadt durch ihre Nähe zu Bangkok geprägt und beherbergt einen großen Teil des internationalen Flughafens Suvarnabhumi sowie bedeutende Industrie- und Logistikzentren. Zu den kulturellen Höhepunkten zählen die \"Ancient City\" (Muang Boran), ein riesiges Freilichtmuseum mit Nachbildungen thailändischer Baudenkmäler, und das Erawan-Museum mit seiner monumentalen dreiköpfigen Elefantenstatue. Jedes Jahr wird die Stadt durch religiöse Feste wie die Phra Samut Chedi Feierlichkeiten belebt, die Tausende von Gläubigen anziehen.",
      hu: "Samut Prakan, amelyet gyakran „Pak Nam”-nak (a folyó torkolata) is neveznek, a Chao Phraya folyó és a Thai-öböl találkozásánál fekszik. A várost az Ayutthaya-korszakban alapították, és tengerparti elhelyezkedése miatt évszázadokon át a főváros stratégiai védelmi bástyájaként szolgált. Az olyan történelmi erődök, mint a Phra Chulachomklao, a régió 19. századi katonai jelentőségéről tanúskodnak. Földrajzilag a várost Bangkokhoz való közelsége jellemzi, és itt található a Suvarnabhumi nemzetközi repülőtér nagy része, valamint jelentős ipari és logisztikai központok. A kulturális látnivalók közé tartozik az „Ősi Város” (Muang Boran), egy hatalmas szabadtéri múzeum thaiföldi műemlékek másolataival, valamint az Erawan Múzeum a monumentális, háromfejű elefántszobrával. A várost minden évben olyan vallási ünnepek élesztik fel, mint a Phra Samut Chedi ünnepségek, amelyek hívők ezreit vonzzák.",
      ro: "Samut Prakan, adesea numit și „Pak Nam” (gura râului), este situat la confluența râului Chao Phraya cu Golful Thailandei. Orașul a fost fondat în perioada Ayutthaya și, datorită locației sale la mare, a servit timp de secole ca post de apărare strategic pentru capitală. Fortărețele istorice precum Phra Chulachomklao atestă importanța militară a regiunii în secolul al XIX-lea. Geografic, orașul este marcat de proximitatea sa de Bangkok și găzduiește o mare parte a aeroportului internațional Suvarnabhumi, precum și centre industriale și logistice importante. Printre atracțiile culturale se numără „Ancient City” (Muang Boran), un uriaș muzeu în aer liber cu replici ale monumentelor thailandeze, și Muzeul Erawan cu monumentala sa statuie a elefantului cu trei capete. În fiecare an, orașul este însuflețit de festivaluri religioase, cum ar fi celebrările Phra Samut Chedi, care atrag mii de credincioși.",
      en: "Samut Prakan, often referred to as \"Pak Nam\" (mouth of the river), is located at the confluence of the Chao Phraya River and the Gulf of Thailand. The city was founded during the Ayutthaya period and, due to its seaside location, served as a strategic defense post for the capital for centuries. Historical forts such as Phra Chulachomklao bear witness to the region's military importance in the 19th century. Geographically, the city is characterized by its proximity to Bangkok and hosts a large part of Suvarnabhumi International Airport as well as significant industrial and logistics centers. Cultural highlights include the \"Ancient City\" (Muang Boran), a vast open-air museum featuring replicas of Thai monuments, and the Erawan Museum with its monumental three-headed elephant statue. Each year, the city is brought to life by religious festivals such as the Phra Samut Chedi celebrations, which attract thousands of devotees.",
      es: "Samut Prakan es un elemento notable de la geografía y la cultura tailandesas. Es una ciudad en la desembocadura del río Chao Phraya en el Golfo de Tailandia, conocida por su industria y sitios históricos. Históricamente conocida como Pak Nam. Sede del Museo Erawan. Importante centro industrial y pesquero. Esta ciudad se encuentra entre los asentamientos característicos de Tailandia, a menudo ubicados a lo largo del Chao Phraya o en la costa de Andamán. Como muchos lugares importantes de Tailandia, combina peculiaridades regionales con el legado del Chao Phraya, el Mekong y la tradición budista. Así, contribuye al perfil versátil de Tailandia entre la costa de Andamán, los campos de arroz y los bosques tropicales.",
      pt: "Samut Prakan é um elemento notável da geografia e cultura tailandesas. É uma cidade na foz do rio Chao Phraya no Golfo da Tailândia, conhecida pela sua indústria e locais históricos. Historicamente conhecida como Pak Nam. Sede do Museu Erawan. Importante centro industrial e pesqueiro. Esta cidade está entre os assentamentos característicos da Tailândia, muitas vezes localizados ao longo do Chao Phraya ou na costa de Andamão. Como muitos lugares importantes na Tailândia, combina peculiaridades regionais com o legado do Chao Phraya, do Mekong e da tradição budista. Assim, contribui para o perfil versátil da Tailândia entre a costa de Andamão, arrozais e florestas tropicais.",
      fr: "Samut Prakan est un élément remarquable de la géographie et de la culture thaïlandaises. C'est une ville située à l'embouchure du fleuve Chao Phraya dans le golfe de Thaïlande, connue pour son industrie et ses sites historiques. Historiquement connue sous le nom de Pak Nam. Siège du musée Erawan. Important centre industriel et halieutique. Cette ville compte parmi les établissements caractéristiques de la Thaïlande, souvent situés le long du Chao Phraya ou sur la côte d'Andaman. Comme de nombreux lieux importants en Thaïlande, elle allie particularités régionales et héritage du Chao Phraya, du Mékong et de la tradition bouddhiste. Elle contribue ainsi au profil diversifié de la Thaïlande entre la côte d'Andaman, les rizières et les forêts tropicales.",
    },
