      hu: ["A Chao Phraya torkolata.", "Itt található a Suvarnabhumi repülőtér.", "Muang Boran szabadtéri múzeum.", "Erawan Múzeum (háromfejű elefánt).", "Phra Chulachomklao stratégiai erőd.", "Az Ayutthaya-korszakban alapították."],
      ro: ["Gura de vărsare a râului Chao Phraya.", "Locația aeroportului Suvarnabhumi.", "Muzeul în aer liber Ancient City.", "Muzeul Erawan (elefant cu trei capete).", "Fortăreața strategică Phra Chulachomklao.", "Fondat în perioada Ayutthaya."],
