      hu: ["Fontos kapu Laosz felé az Első Thai-Laoszi Barátság Hídon keresztül.", "Híres a Naga tűzgolyók jelenségéről.", "Nyugodt, folyóparti hangulata van."],
      ro: ["O poartă importantă către Laos prin intermediul Primului Pod al Prieteniei Thailando-Laoțiene.", "Cunoscut pentru fenomenul globurilor de foc Naga.", "Are o atmosferă relaxată pe malul râului."],
      en: ["An important gateway to Laos via the First Thai–Lao Friendship Bridge.", "Known for the Naga fireballs phenomenon.", "Has a relaxed, riverside atmosphere."],
