      pt: ["Uma importante porta de entrada para o Laos através da Primeira Ponte da Amizade Tailândia-Laos.", "Conhecida pelo fenómeno das bolas de fogo Naga.", "Tem uma atmosfera relaxada nas margens do rio."],
      fr: ["Une importante porte d'entrée vers le Laos via le premier pont de l'amitié thaï-laotienne.", "Connue pour le phénomène des boules de feu Naga.", "Possède une atmosphère détendue au bord du fleuve."],
